  "function_name": "analyze_chart_patterns",
  "function_arg": {
    "stock_code": "603466",
    "kline_data": "获取到的K线数据"
  }
}
```

```json
{
  "function_name": "calculate_ma",
  "function_arg": {
    "stock_code": "603466",
    "kline_data": "获取到的K线数据",
    "ma_periods": [5, 10, 20]  // 计算5日、10日和20日的移动平均线
  }
}
```

```json
{
  "function_name": "analyze_trend",
  "function_arg": {
    "stock_code": "603466",
    "kline_data": "获取到的K线数据",
    "ma_data": "计算得到的移动平均线数据"
  }
}
```

```json
